def _getitem_axis(self, key, axis: int):
    key = item_from_zerodim(key)
    if is_iterator(key):
        key = list(key)

    labels = self.obj._get_axis(axis)
    key = labels._get_partial_string_timestamp_match_key(key)

    if isinstance(key, slice):
        self._validate_key(key, axis)
        return self._get_slice_axis(key, axis=axis)
    elif com.is_bool_indexer(key):
        return self._getbool_axis(key, axis=axis)
    elif is_list_like_indexer(key):

        # convert various list-like indexers
        # to a list of keys
        # we will use the *values* of the object
        # and NOT the index if its a PandasObject
        if isinstance(labels, ABCMultiIndex):

            if isinstance(key, (ABCSeries, np.ndarray)) and key.ndim <= 1:
                # Series, or 0,1 ndim ndarray
                # GH 14730
                key = list(key)
            elif isinstance(key, ABCDataFrame):
                # GH 15438
                raise NotImplementedError(
                    "Indexing a MultiIndex with a "
                    "DataFrame key is not "
                    "implemented"
                )
            elif hasattr(key, "ndim") and key.ndim > 1:
                raise NotImplementedError(
                    "Indexing a MultiIndex with a "
                    "multidimensional key is not "
                    "implemented"
                )

            # Check if the key is a list-like object of integers and not a tuple
            if (
                not isinstance(key, tuple)
                and len(key)
                and isinstance(key[0], int)
            ):
                # If the first level of the MultiIndex is integer-based,
                # we should raise a KeyError if the integer is not found in the index
                if not all(k in labels for k in key):
                    raise KeyError(f"{key} not in index")

                # if it's not a tuple and the first level of the index is integer,
                # and the key is within the bounds of the first level, we can proceed
                # with the index lookup
                if all(0 <= k < len(labels.levels[0]) for k in key):
                    locs = [labels.get_loc(k) for k in key]
                    indexer = [slice(None)] * self.ndim
                    indexer[axis] = locs
                    return self.obj.iloc[tuple(indexer)]

            # if the key is not a list-like object of integers and not a tuple,
            # or it's a tuple, we should proceed with the original logic of the function
            if (
                not isinstance(key, tuple)
                and len(key)
                and not isinstance(key[0], tuple)
            ):
                key = tuple([key])

        # an iterable multi-selection
        if not (isinstance(key, tuple) and isinstance(labels, ABCMultiIndex)):

            if hasattr(key, "ndim") and key.ndim > 1:
                raise ValueError("Cannot index with multidimensional key")

            # Check if all elements in the key are integers and are within the bounds of the labels
            if all(isinstance(k, int) and 0 <= k < len(labels) for k in key):
                locs = [labels.get_loc(k) for k in key]
                indexer = [slice(None)] * self.ndim
                indexer[axis] = locs
                return self.obj.iloc[tuple(indexer)]
            else:
                return self._getitem_iterable(key, axis=axis)

        # nested tuple slicing
        if is_nested_tuple(key, labels):
            locs = labels.get_locs(key)
            indexer = [slice(None)] * self.ndim
            indexer[axis] = locs
            return self.obj.iloc[tuple(indexer)]

    # check if key is an integer
    if isinstance(key, int) and isinstance(labels, ABCMultiIndex):
        if 0 <= key < len(labels):
            return self._getitem_iterable([key], axis=axis)
        else:
            raise KeyError(f"{key} not in index")

    # fall thru to straight lookup
    self._validate_key(key, axis)
    return self._get_label(key, axis=axis)
